uint8_t reportKind(uint8_t id){if(id==SH2_ACCELEROMETER)return 1;if(id==SH2_GYROSCOPE_CALIBRATED)return 2;if(id==SH2_ROTATION_VECTOR||id==SH2_GAME_ROTATION_VECTOR)return 3;if(id==SH2_MAGNETIC_FIELD_CALIBRATED)return 4;if(id==SH2_LINEAR_ACCELERATION)return 5;return 0;}
