  ok=enableOne(2,SH2_GYROSCOPE_CALIBRATED,10000UL,phase)&&ok;ok=enableOne(1,SH2_ACCELEROMETER,10000UL,phase)&&ok;ok=enableOne(4,SH2_MAGNETIC_FIELD_CALIBRATED,kMagneticIntervalUs,phase)&&ok;
